    de_minimis_usd: 272,
    clearance_process_en: 'Federal Customs Authority (FCA) oversees, but each emirate has its own customs authority. Dubai Customs uses Mirsal 2 system. Standard 5% GCC common external tariff on most goods. Free zones have separate import regimes.',
    clearance_process_ru: 'Федеральная таможня (FCA) контролирует, но каждый эмират имеет свою таможню. Таможня Дубая использует систему Mirsal 2. Стандартный 5% тариф ОТТ ССЗ на большинство товаров. Свободные зоны имеют отдельный импортный режим.',
    clearance_time_days: '1-3',
    certificate_of_origin_en: 'UAE Chambers of Commerce issue certificates. GCC-origin goods duty-free within GCC. Certificates required for preferential treatment under GCC FTAs with Singapore, EFTA.',
    certificate_of_origin_ru: 'Торговые палаты ОАЭ выдают сертификаты. Товары происхождения ССЗ — беспошлинно внутри ССЗ. Сертификаты требуются для льготного режима по ЗСТ ССЗ с Сингапуром, EFTA.',
    import_license_info_en: 'Trade license required for commercial imports. Restricted items include alcohol (special permit), pork products, pharmaceuticals, and weapons. ESMA certification for certain consumer products.',
    import_license_info_ru: 'Торговая лицензия обязательна для коммерческого импорта. Ограниченные товары: алкоголь (специальное разрешение), свинина, фармацевтика, оружие. Сертификация ESMA для ряда потребительских товаров.',
    customs_reality_en: 'UAE customs is fast and business-friendly. Dubai and Abu Dhabi are major re-export hubs. Flat 5% duty makes calculations simple. Free zones (JAFZA, DAFZA) allow duty-free import for re-export. VAT at 5% applies since 2018. Express shipments clear within hours.',
    customs_reality_ru: 'Таможня ОАЭ быстрая и дружелюбная к бизнесу. Дубай и Абу-Даби — крупные хабы реэкспорта. Плоская пошлина 5% упрощает расчёты. Свободные зоны (JAFZA, DAFZA) позволяют беспошлинный ввоз для реэкспорта. НДС 5% применяется с 2018 года. Экспресс-грузы оформляются за часы.',
    vat_rate: '5%',
    vat_applies_to: 'CIF value + duty. Some goods exempt (basic food, healthcare, education).',
