    de_minimis_usd: 300,
    clearance_process_en: 'Singapore Customs uses TradeNet electronic system. Singapore is a free port — virtually zero import duties (except alcohol, tobacco, motor vehicles, petroleum). GST applies to all imports. Goods under S$400 are GST-exempt.',
    clearance_process_ru: 'Таможня Сингапура использует систему TradeNet. Сингапур — свободный порт: практически нулевые пошлины (кроме алкоголя, табака, автомобилей, нефтепродуктов). GST применяется ко всем импортным товарам. Товары до S$400 освобождены от GST.',
    clearance_time_days: '1-2',
    certificate_of_origin_en: 'Singapore Customs or authorized bodies issue certificates. Preferential certificates under RCEP, CPTPP, ASEAN FTA, Singapore-US FTA, Singapore-EU FTA. Electronic certificates via EODES.',
    certificate_of_origin_ru: 'Таможня Сингапура или уполномоченные органы выдают сертификаты. Преференциальные сертификаты по RCEP, CPTPP, ASEAN FTA, Singapore-US FTA, Singapore-EU FTA. Электронные сертификаты через EODES.',
    import_license_info_en: 'Most goods imported freely. Controlled goods (pharmaceuticals, hazardous chemicals, media content, weapons, wildlife) require permits from respective agencies (HSA, NEA, IMDA).',
    import_license_info_ru: 'Большинство товаров импортируется свободно. Контролируемые товары (фармацевтика, опасные химикаты, медиаконтент, оружие, дикая природа) требуют разрешений от соответствующих агентств (HSA, NEA, IMDA).',
    customs_reality_en: 'One of the most efficient customs systems in the world. TradeNet processes declarations in minutes. As a free port, virtually all goods are duty-free. Only GST at 9% (raised from 8% in 2024) applies. Express and postal shipments clear rapidly.',
    customs_reality_ru: 'Одна из самых эффективных таможенных систем в мире. TradeNet обрабатывает декларации за минуты. Как свободный порт, почти все товары беспошлинны. Применяется только GST 9% (повышен с 8% в 2024). Экспресс- и почтовые отправления оформляются быстро.',
    vat_rate: '9% GST',
    vat_applies_to: 'CIF value. No duty on most goods so GST is on CIF only. Vendor-collected for B2C low-value goods under the OVR scheme.',
    customs_tariff_url: 'https://www.customs.gov.sg/businesses/valuation-duties-taxes-fees/duties-and-dutiable-goods',
