    import_license_info_ru: 'Импортные лицензии для контролируемых товаров: транспорт, оборудование свыше определённой стоимости, фармацевтика, продукты, косметика (регистрация FDA), сельхозпродукция. Стандарты TISI обязательны для ряда товаров.',
