    customs_reality_ru: 'Таможня Таиланда улучшилась с e-Customs, но почтовые отправления всё ещё медленные. Личные посылки через Thailand Post могут оформляться 1-2 недели. Экспресс-курьеры намного быстрее. Косметика и продукты требуют уведомления Thai FDA, что может существенно задержать оформление.',
