    de_minimis_usd: 50,
    clearance_process_en: 'Receita Federal (Federal Revenue) manages customs via Siscomex electronic system. Personal imports under $50 from individuals are duty-free. The Remessa Conforme program allows e-commerce platforms to pre-clear with reduced ICMS. Commercial imports require CPF/CNPJ and licensed customs broker.',
    clearance_process_ru: 'Федеральная налоговая служба (Receita Federal) управляет таможней через систему Siscomex. Личный импорт до $50 от физлиц — беспошлинный. Программа Remessa Conforme позволяет маркетплейсам проходить упрощённое оформление со сниженным ICMS. Коммерческий импорт требует CPF/CNPJ и лицензированного брокера.',
    clearance_time_days: '7-60',
    certificate_of_origin_en: 'Local trade federations and Chambers of Commerce issue certificates. Preferential certificates under Mercosur, Mercosur-EU (pending), ACE agreements with Latin American partners. Form A for GSP.',
    certificate_of_origin_ru: 'Местные торговые федерации и торговые палаты выдают сертификаты. Преференциальные сертификаты по Mercosur, Mercosur-EU (в процессе), соглашениям ACE с латиноамериканскими партнёрами. Форма A для ОСП.',
    import_license_info_en: 'Import license (LI) required for many products via Siscomex. ANVISA approval for health products, cosmetics, food. INMETRO certification for regulated products. Automatic and non-automatic licensing depending on product category.',
    import_license_info_ru: 'Импортная лицензия (LI) обязательна для многих товаров через Siscomex. Одобрение ANVISA для медтоваров, косметики, продуктов. Сертификация INMETRO для регулируемых товаров. Автоматическое и неавтоматическое лицензирование в зависимости от категории.',
    customs_reality_en: 'Notoriously slow and expensive. Import duties among world\'s highest. Customs can hold packages 30-60 days. Total tax burden (duty + IPI + ICMS + PIS/COFINS) can reach 80-100% of product value. The Remessa Conforme program (2023) improved things for marketplace purchases, reducing tax to 17% ICMS for items under $50.',
    customs_reality_ru: 'Печально известна медленностью и дороговизной. Импортные пошлины одни из самых высоких в мире. Таможня может удерживать посылки 30-60 дней. Общая налоговая нагрузка (пошлина + IPI + ICMS + PIS/COFINS) может достигать 80-100% стоимости товара. Программа Remessa Conforme (2023) улучшила ситуацию для покупок на маркетплейсах, снизив налог до 17% ICMS для товаров до $50.',
    vat_rate: '17-25% ICMS + 9.25% PIS/COFINS',
    vat_applies_to: 'Complex cascading taxes: Import duty on CIF, then IPI on (CIF+duty), then ICMS and PIS/COFINS on the compounded total.',
    customs_tariff_url: 'https://www.gov.br/receitafederal/pt-br/assuntos/aduana-e-comercio-exterior/classificacao-fiscal-de-mercadorias/consulta-a-tec',
    trade_statistics_url: 'https://comexstat.mdic.gov.br/en/home',
    certificate_of_origin_url: 'https://www.gov.br/siscomex/pt-br/informacoes/certificado-de-origem',
    import_regulations_url: 'https://www.gov.br/receitafederal/pt-br/assuntos/aduana-e-comercio-exterior',
