    de_minimis_usd: 50,
    clearance_process_en: 'Mexico\'s SAT (Tax Administration Service) handles customs through VUCEM (Single Window for Foreign Trade). Imports require a pedimento (customs declaration) filed by a licensed customs broker. USMCA preferential rates apply for US/Canada origin goods.',
    clearance_process_ru: 'SAT (Служба налогового администрирования Мексики) управляет таможней через VUCEM (единое окно внешней торговли). Для импорта требуется pedimento (таможенная декларация), подаваемая лицензированным таможенным брокером. Преференциальные ставки USMCA для товаров из США/Канады.',
    clearance_time_days: '2-7',
    certificate_of_origin_en: 'USMCA certificate for preferential rates with US and Canada. Self-certification accepted under USMCA. For other FTAs, specific forms required. Mexico has FTAs with EU, Japan, and many Latin American countries.',
    certificate_of_origin_ru: 'Сертификат USMCA для преференциальных ставок с США и Канадой. Самосертификация принимается по USMCA. Для других ЗСТ требуются специальные формы. У Мексики ЗСТ с ЕС, Японией и многими странами Латинской Америки.',
    import_license_info_en: 'Import permits required for agricultural products, pharmaceuticals, chemicals, used vehicles, and firearms. COFEPRIS regulates food and health products. NOM certification for product safety standards required for many consumer goods.',
    import_license_info_ru: 'Разрешения на импорт требуются для сельхозпродукции, фармацевтики, химикатов, подержанных автомобилей и оружия. COFEPRIS регулирует продукты питания и товары для здоровья. Сертификация NOM по стандартам безопасности для многих потребительских товаров.',
    customs_reality_en: 'Improving with digital customs. SAT handles clearance. Can be slow for postal — 2-4 weeks. Express couriers clear in 1-2 days.',
    customs_reality_ru: 'Улучшается с цифровизацией таможни. SAT занимается оформлением. Почтовые отправления могут идти 2-4 недели. Экспресс-курьеры оформляют за 1-2 дня.',
    vat_rate: '16% IVA',
    vat_applies_to: 'CIF value + duty. IVA applies to all imports. Border zones may have reduced rate of 8%.',
    customs_tariff_url: 'https://www.siicex.gob.mx/portalSiicex/',
    trade_statistics_url: 'https://www.inegi.org.mx/programas/exporta/',
    certificate_of_origin_url: 'https://www.gob.mx/se/acciones-y-programas/comercio-exterior-tratados-y-acuerdos',
