    clearance_process_ru: 'Польша использует Единый таможенный тариф ЕС (CCT) и систему TARIC. Таможенные декларации через электронную систему AIS/CELINA. Как член ЕС, товары из других стран ЕС перемещаются свободно. Импорт из-за пределов ЕС требует стандартной таможенной декларации (SAD).',
