    import_license_info_en: 'EU-wide licensing for controlled goods: dual-use items, weapons, certain textiles and steel quotas. SANEPID certification for food. Polish Office for Registration of Medicinal Products for pharmaceuticals.',
    import_license_info_ru: 'Общеевропейское лицензирование контролируемых товаров: товары двойного назначения, оружие, квоты на текстиль и сталь. Сертификация SANEPID для продуктов. Управление по регистрации лекарственных средств для фармацевтики.',
    customs_reality_en: 'Efficient EU customs procedures. Poczta Polska parcels clear within 1-3 days. Express couriers same-day clearance. IOSS system for e-commerce under €150 simplifies VAT. Polish customs modernized significantly since EU accession.',
    customs_reality_ru: 'Эффективные таможенные процедуры ЕС. Посылки Poczta Polska проходят за 1-3 дня. Экспресс-курьеры — оформление в тот же день. Система IOSS для e-commerce до €150 упрощает НДС. Польская таможня значительно модернизирована после вступления в ЕС.',
    vat_rate: '23%',
    vat_applies_to: 'CIF value + duty. Reduced rates: 8% for food, books, pharmaceuticals; 5% for basic food products.',
