    clearance_process_ru: 'Федеральное управление таможни и пограничной безопасности Швейцарии (FOCBS) использует электронную систему e-dec. Швейцария применяет пошлины по весу для многих товаров (не адвалорные). Член ЕАСТ с обширной сетью ЗСТ.',
