    clearance_process_ru: 'Саудовская таможня (Управление закята, налогов и таможни — ZATCA) управляет импортом через платформу единого окна FASAH. Система соответствия продукции SABER обязательна для регулируемых товаров. Применяется Единый таможенный закон GCC.',
