    clearance_process_ru: 'Таможенное управление Египта использует систему единого окна Nafeza для содействия торговле. Все импортные товары требуют регистрации в системе предварительной информации о грузах (ACI) до отправки. Таможенный брокер обязателен для коммерческого импорта.',
