    import_license_info_en: 'Standards Institution of Israel (SII) approval for many consumer goods. Ministry of Health for food and cosmetics. AMAR system for import licensing. Kosher certification may be required for food products.',
    import_license_info_ru: 'Одобрение Института стандартов Израиля (SII) для многих потребительских товаров. Министерство здравоохранения для продуктов и косметики. Система AMAR для импортных лицензий. Сертификация кошер может потребоваться для продуктов питания.',
