    clearance_process_ru: 'Налоговая служба Южной Африки (SARS) управляет таможней через программу модернизации таможни. Электронные декларации через систему EDI. Лицензированный таможенный брокер обязателен для коммерческого импорта. SACU (Южноафриканский таможенный союз) применяет общий внешний тариф.',
