    customs_reality_en: 'War-affected routes. Postal service disrupted. DHL/UPS still operate. Western Ukraine clearance faster.',
    customs_reality_ru: 'Маршруты затронуты войной. Почтовая служба нарушена. DHL/UPS продолжают работать. Оформление в Западной Украине быстрее.',
