    de_minimis_usd: 200,
    clearance_process_en: 'State Revenue Committee (KGD) under Ministry of Finance handles customs. EAEU (Eurasian Economic Union) Common Customs Tariff applies. Electronic declaration through ASTANA-1 information system. Goods from EAEU members (Russia, Belarus, Armenia, Kyrgyzstan) move freely.',
    clearance_process_ru: 'Комитет государственных доходов (КГД) при Министерстве финансов управляет таможней. Применяется Единый таможенный тариф ЕАЭС. Электронное декларирование через систему АСТАНА-1. Товары из стран ЕАЭС (Россия, Беларусь, Армения, Кыргызстан) перемещаются свободно.',
    clearance_time_days: '3-10',
    certificate_of_origin_en: 'EAEU certificate CT-1 for trade within the union. Form A for GSP. Atameken (National Chamber of Entrepreneurs) issues certificates. EAC conformity mark for EAEU technical regulations.',
    certificate_of_origin_ru: 'Сертификат ЕАЭС СТ-1 для торговли внутри союза. Форма А для ОСП. Атамекен (Национальная палата предпринимателей) выдаёт сертификаты. Знак EAC для технических регламентов ЕАЭС.',
    import_license_info_en: 'EAEU unified licensing for controlled goods. National permits for pharmaceuticals, weapons, radioactive materials. EAC conformity declaration/certification for consumer goods. Ministry of Trade for quota goods.',
    import_license_info_ru: 'Единое лицензирование ЕАЭС для контролируемых товаров. Национальные разрешения для фармацевтики, оружия, радиоактивных материалов. Декларация/сертификация соответствия EAC для потребительских товаров. Министерство торговли для квотируемых товаров.',
    customs_reality_en: 'Modernizing rapidly. ASTANA-1 system improving efficiency. EAEU membership means no customs for Russian/Belarusian goods. Almaty and Nur-Sultan customs relatively efficient. Remote border posts can be slow. Express couriers 3-5 days.',
    customs_reality_ru: 'Быстро модернизируется. Система АСТАНА-1 повышает эффективность. Членство в ЕАЭС означает отсутствие таможни для российских/белорусских товаров. Таможня в Алматы и Нур-Султане относительно эффективна. Удалённые пограничные посты могут быть медленными. Экспресс-курьеры — 3-5 дней.',
    vat_rate: '12%',
    vat_applies_to: 'CIF value + duty. Flat 12% rate for most goods. Some food items and medical supplies zero-rated.',
    customs_tariff_url: 'https://kgd.gov.kz/en/content/customs-tariff',
    trade_statistics_url: 'https://stat.gov.kz/en/industries/economy/foreign-trade/',
