    clearance_process_ru: 'Генеральный департамент таможни Вьетнама (GDVC) использует электронную систему VNACCS/VCIS. Система светофора: зелёный (автовыпуск), жёлтый (проверка документов), красный (физический осмотр). Множество ЗСТ включая CPTPP, EVFTA, RCEP.',
