    import_license_info_en: 'Automatic import licenses for most goods. Special permits for pharmaceuticals (Drug Administration of Vietnam), food (Ministry of Health), telecom equipment (Ministry of Information). Quality inspection for many consumer goods.',
    import_license_info_ru: 'Автоматические импортные лицензии для большинства товаров. Специальные разрешения для фармацевтики (Управление лекарств Вьетнама), продуктов (Минздрав), телеком-оборудования (Министерство информации). Проверка качества для многих потребительских товаров.',
    customs_reality_en: 'Improving rapidly. VNACCS electronic customs. Can be strict on used goods and electronics.',
