    clearance_process_ru: 'Генеральный директорат таможни и акцизов (DJBC) использует INSW (Национальное единое окно Индонезии) и электронную систему CEISA. Идентификационный номер импортёра (API) обязателен. АСЕАН, RCEP и двусторонние ЗСТ обеспечивают преференциальные ставки.',
