    clearance_process_ru: 'Налоговое управление Уганды (URA) использует электронную таможенную систему ASYCUDA World. Применяется Единый внешний тариф Восточноафриканского сообщества. Электронное единое окно (eSW) для содействия торговле. TIN обязателен для всех импортёров.',
