    import_license_info_en: 'UNBS (Uganda National Bureau of Standards) for product quality. National Drug Authority for pharmaceuticals. Import permits from URA. Pre-Export Verification of Conformity (PVoC) for regulated goods.',
    import_license_info_ru: 'UNBS (Национальное бюро стандартов Уганды) для качества продукции. Национальное управление лекарств для фармацевтики. Разрешения на импорт от URA. Предэкспортная проверка соответствия (PVoC) для регулируемых товаров.',
